<?php require_once __DIR__.'/../config/config.php';admin_required();if(isset($_GET['type'])){if(!file_exists(__DIR__.'/../vendor/autoload.php'))exit('Install PhpSpreadsheet: composer require phpoffice/phpspreadsheet');require __DIR__.'/../vendor/autoload.php';$type=$_GET['type'];$map=['orders'=>"SELECT o.order_code AS `Order ID`,c.name AS `Customer Name`,c.phone AS `Phone`,c.email AS `Email`,oi.product_name AS `Product`,oi.quantity AS `Quantity`,oi.unit_price AS `Unit Price`,o.total AS `Order Total`,o.payment_method AS `Payment`,o.created_at AS `Order Date`,o.status AS `Status`,c.address AS `Address` FROM orders o JOIN customers c ON c.id=o.customer_id JOIN order_items oi ON oi.order_id=o.id",'products'=>"SELECT id,name,category,price,sale_price,stock,active,created_at FROM products",'sales'=>"SELECT DATE(created_at) AS `Date`,COUNT(*) AS `Orders`,SUM(total) AS `Sales` FROM orders WHERE status<>'Cancelled' GROUP BY DATE(created_at) ORDER BY DATE(created_at)"];if(!isset($map[$type]))exit('Invalid report');$rows=$pdo->query($map[$type])->fetchAll();$sheet=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet->getActiveSheet()->fromArray(array_keys($rows[0]??['No records'=>'']),null,'A1');if($rows)$sheet->getActiveSheet()->fromArray(array_map('array_values',$rows),null,'A2');$writer=new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($sheet);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename=\"watcheserror-'.$type.'.xlsx\"');$writer->save('php://output');exit;}require 'layout.php';?><h1>Excel Reports</h1><p>Exports are generated live from MySQL records.</p><div class="row g-3"><?php foreach(['orders'=>'All Orders','products'=>'All Products','sales'=>'Sales Report'] as $k=>$v):?><div class="col-md-4"><div class="admin-card"><h5><?=$v?></h5><a class="btn btn-gold" href="?type=<?=$k?>">Download .xlsx</a></div></div><?php endforeach;?></div><?php require 'end.php';?>